mapper.select:
SELECT cbr.id, cbr.user_id, u.username, u.nickname, cbr.behavior_type, cbr.behavior_name, cbr.behavior_value, cbr.carbon_reduction, cbr.points, cbr.description, cbr.proof_image, cbr.audit_status, CASE cbr.audit_status WHEN 0 THEN '待审核' WHEN 1 THEN '审核通过' WHEN 2 THEN '审核拒绝' END AS audit_status_text, cbr.audit_user_id, au.username AS audit_user_name, cbr.audit_time, cbr.audit_remark, cbr.create_time FROM carbon_behavior_record cbr LEFT JOIN user u ON cbr.user_id = u.id LEFT JOIN user au ON cbr.audit_user_id = au.id WHERE 1=1
AND cbr.user_id = #{userId}
AND cbr.behavior_type = #{behaviorType}
AND cbr.audit_status = #{auditStatus}
AND cbr.create_time >= #{startTime}
AND cbr.create_time <= #{endTime}
ORDER BY cbr.create_time DESC

SELECT cbr.id, cbr.user_id, u.username, u.nickname, cbr.behavior_type, cbr.behavior_name, cbr.behavior_value, cbr.carbon_reduction, cbr.points, cbr.description, cbr.proof_image, cbr.audit_status, CASE cbr.audit_status WHEN 0 THEN '待审核' WHEN 1 THEN '审核通过' WHEN 2 THEN '审核拒绝' END AS audit_status_text, cbr.create_time FROM carbon_behavior_record cbr LEFT JOIN user u ON cbr.user_id = u.id WHERE cbr.audit_status = 0
AND cbr.user_id = #{userId}
AND cbr.behavior_type = #{behaviorType}
AND cbr.create_time >= #{startTime}
AND cbr.create_time <= #{endTime}
ORDER BY cbr.create_time ASC

SELECT cbr.id, cbr.user_id, u.username, u.nickname, cbr.behavior_type, cbr.behavior_name, cbr.behavior_value, cbr.carbon_reduction, cbr.points, cbr.description, cbr.proof_image, cbr.audit_status, CASE cbr.audit_status WHEN 0 THEN '待审核' WHEN 1 THEN '审核通过' WHEN 2 THEN '审核拒绝' END AS audit_status_text, cbr.audit_user_id, au.username AS audit_user_name, cbr.audit_time, cbr.audit_remark, cbr.create_time FROM carbon_behavior_record cbr LEFT JOIN user u ON cbr.user_id = u.id LEFT JOIN user au ON cbr.audit_user_id = au.id WHERE 1=1
AND u.username LIKE CONCAT('%', #{username}, '%')
AND cbr.behavior_type = #{behaviorType}
AND cbr.audit_status = #{auditStatus}
AND cbr.create_time >= #{startTime}
AND cbr.create_time <= #{endTime}
ORDER BY cbr.create_time DESC

SELECT 
    COUNT(*) AS totalCount,
    SUM(CASE WHEN cbr.audit_status = 0 THEN 1 ELSE 0 END) AS pendingCount,
    SUM(CASE WHEN cbr.audit_status = 1 THEN 1 ELSE 0 END) AS passedCount,
    SUM(CASE WHEN cbr.audit_status = 2 THEN 1 ELSE 0 END) AS rejectedCount
FROM carbon_behavior_record cbr
LEFT JOIN user u ON cbr.user_id = u.id
WHERE 1=1

    AND u.username LIKE CONCAT('%', #{username}, '%')


    AND cbr.behavior_type = #{behaviorType}


    AND cbr.audit_status = #{auditStatus}


    AND cbr.create_time >= #{startTime}


    AND cbr.create_time <= #{endTime}

SELECT cbr.behavior_type AS behaviorType, cbr.behavior_name AS behaviorName, br.unit AS unit, COUNT(*) AS count, SUM(cbr.behavior_value) AS totalValue, SUM(cbr.carbon_reduction) AS totalCarbon, SUM(cbr.points) AS totalPoints, ROUND(COUNT(*) * 100.0 / ( SELECT COUNT(*) FROM carbon_behavior_record WHERE audit_status = 1 AND user_id = #{userId}
AND create_time >= #{startTime}
AND create_time <= #{endTime}
), 2) AS percentage FROM carbon_behavior_record cbr LEFT JOIN behavior_rule br ON cbr.behavior_type = br.behavior_type WHERE cbr.audit_status = 1
AND cbr.user_id = #{userId}
AND cbr.create_time >= #{startTime}
AND cbr.create_time <= #{endTime}
GROUP BY cbr.behavior_type, cbr.behavior_name, br.unit ORDER BY count DESC

SELECT DATE_FORMAT(create_time, '%Y-%m') AS month, COUNT(*) AS count, SUM(carbon_reduction) AS carbon, SUM(points) AS points FROM carbon_behavior_record WHERE audit_status = 1
AND user_id = #{userId}
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month DESC LIMIT 12

SELECT COUNT(*)
FROM carbon_behavior_record
WHERE user_id = #{userId}

    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

SELECT COUNT(*)
FROM carbon_behavior_record
WHERE user_id = #{userId}
AND audit_status = #{auditStatus}

    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

SELECT cbr.behavior_type AS behaviorType, cbr.behavior_name AS behaviorName, br.unit AS unit, COUNT(*) AS count, SUM(cbr.behavior_value) AS totalValue, SUM(cbr.carbon_reduction) AS totalCarbon, SUM(cbr.points) AS totalPoints, ROUND(COUNT(*) * 100.0 / ( SELECT COUNT(*) FROM carbon_behavior_record WHERE audit_status = 1
AND create_time >= #{startTime}
AND create_time <= #{endTime}
